function onGMWindowLoad(){if(-1!=document.title.toString().indexOf("Meet - ")){chrome.runtime.connect({name:"gmeet"}).postMessage({action:"getGoogleMeetUrl",url:window.location.href})}}function callWindowLoadWithTimeOutGm(){setTimeout(onGMWindowLoad,2e3)}window.addEventListener("load",callWindowLoadWithTimeOutGm,!1);